     * A long press is handled by the view's OnLongClickListener (e.g. opening the comment
     * menu), so the link itself must not be opened in that case.
     */
    private long downTime = 0;
    private float downX = 0;
    private float downY = 0;
    private boolean isLongPress = false;

    public static LocalLinkMovementMethod getInstance() {
        if (sInstance == null)
            sInstance = new LocalLinkMovementMethod();

        return sInstance;
    }

    @Override
    public boolean onTouchEvent(TextView widget, Spannable buffer, MotionEvent event) {
        int action = event.getActionMasked();

        if (action == MotionEvent.ACTION_DOWN) {
            downTime = event.getEventTime();
            downX = event.getX();
            downY = event.getY();
            isLongPress = false;
        } else if (action == MotionEvent.ACTION_MOVE) {
            // Moving too far means this is a scroll/drag, not a tap on the link
            float slop = ViewConfiguration.get(widget.getContext()).getScaledTouchSlop();
            if (Math.abs(event.getX() - downX) > slop || Math.abs(event.getY() - downY) > slop) {
                isLongPress = true;
            }
        } else if (action == MotionEvent.ACTION_CANCEL) {
            isLongPress = true;
        }

        if (action == MotionEvent.ACTION_UP ||
                action == MotionEvent.ACTION_DOWN) {
            int x = (int) event.getX();
            int y = (int) event.getY();

            x -= widget.getTotalPaddingLeft();
            y -= widget.getTotalPaddingTop();

            x += widget.getScrollX();
            y += widget.getScrollY();

            Layout layout = widget.getLayout();
            if (layout == null) {
                return Touch.onTouchEvent(widget, buffer, event);
            }
            int line = layout.getLineForVertical(y);
            int off = layout.getOffsetForHorizontal(line, x);

            ClickableSpan[] link = buffer.getSpans(off, off, ClickableSpan.class);

            if (link.length != 0) {
                if (action == MotionEvent.ACTION_UP) {
                    Selection.removeSelection(buffer);
                    // Only follow the link if this was an actual (short) tap. A long press
                    // is consumed by the OnLongClickListener which shows a menu instead.
                    if (!isLongPress && !isLongPressDuration(event)) {
                        link[0].onClick(widget);
                    }
                    isLongPress = false;
                } else if (action == MotionEvent.ACTION_DOWN) {
                    Selection.setSelection(buffer,
                            buffer.getSpanStart(link[0]),
                            buffer.getSpanEnd(link[0]));
                }

                return true;
            } else {
                Selection.removeSelection(buffer);
                Touch.onTouchEvent(widget, buffer, event);
                return false;
            }
        }
        return Touch.onTouchEvent(widget, buffer, event);
    }

    private boolean isLongPressDuration(MotionEvent event) {
        return (event.getEventTime() - downTime) >= ViewConfiguration.getLongPressTimeout();
    }
}
